<?php
namespace App\Http\Controllers; use App\Models\{AssistanceRequest,SeniorCitizen}; use Illuminate\Http\Request;
class AssistanceRequestController extends Controller { public function index(Request $r){$q=AssistanceRequest::with('seniorCitizen');if($s=$r->get('search'))$q->whereHas('seniorCitizen',fn($w)=>$w->where('first_name','like',"%$s%")->orWhere('last_name','like',"%$s%"));if($st=$r->get('status'))$q->where('status',$st);return view('assistance.index',['requests'=>$q->latest()->paginate(10)->withQueryString()]);} public function create(){return view('assistance.form',['requestItem'=>new AssistanceRequest,'seniors'=>SeniorCitizen::where('status','Active')->orderBy('last_name')->get()]);} public function store(Request $r){AssistanceRequest::create($this->data($r));return redirect()->route('assistance.index')->with('success','Assistance request recorded.');} public function show(AssistanceRequest $assistanceRequest){return view('assistance.show',['item'=>$assistanceRequest->load('seniorCitizen')]);} public function edit(AssistanceRequest $assistanceRequest){return view('assistance.form',['requestItem'=>$assistanceRequest,'seniors'=>SeniorCitizen::orderBy('last_name')->get()]);} public function update(Request $r,AssistanceRequest $assistanceRequest){$d=$this->data($r);if(in_array($d['status'],['Approved','Rejected','Completed'])&&!$d['date_resolved'])$d['date_resolved']=now()->toDateString();$assistanceRequest->update($d);return redirect()->route('assistance.show',$assistanceRequest)->with('success','Request status updated.');} public function destroy(AssistanceRequest $assistanceRequest){$assistanceRequest->delete();return redirect()->route('assistance.index')->with('success','Request deleted.');} private function data(Request $r){return $r->validate(['senior_citizen_id'=>'required|exists:senior_citizens,id','request_type'=>'required|string|max:120','description'=>'required|string|max:2000','date_requested'=>'required|date','status'=>'required|in:Pending,Under Review,Approved,Rejected,Completed','review_notes'=>'nullable|string|max:2000','date_resolved'=>'nullable|date']);} }
